std::expected<Response, Error> with_retry(auto op, const Policy& p) {
  std::expected<Response, Error> last = std::unexpected(Error::not_attempted);
  for (int attempt = 1; attempt <= p.max_attempts; ++attempt) {
    last = op();
    if (last) return last;
    if (!p.transient(last.error()) || attempt == p.max_attempts) return last;
    std::this_thread::sleep_for(p.delay(attempt));
  }
  return last;
}
